const cfg = $input.first().json;
const authorized = cfg.authorization === 'Yes \u2014 I own or am contractually authorized to research/assess this system';

const BLOCKLIST = [
  'exploit code', 'ransomware', 'ddos', 'denial of service attack', 'backdoor',
  'bypass antivirus', 'bypass edr', 'keylogger', 'botnet', '0day weaponiz', 'zero-day weaponiz',
  'credential stuffing tool', 'phishing kit', 'malware sample', 'rootkit', 'brute force script',
  'sql injection payload', 'reverse shell', 'c2 server', 'command and control server',
  'wipe logs', 'cover my tracks', 'unauthorized access', 'crack password', 'crypter',
  'stealer log', 'carding', 'skimmer', 'weaponize', 'attack script'
];

const haystack = `${cfg.target} ${cfg.details} ${cfg.request_type}`.toLowerCase();
const matched = BLOCKLIST.filter(term => haystack.includes(term));

const blocked = !authorized || matched.length > 0;
let reason = '';
if (!authorized) reason += 'Authorization was not confirmed. ';
if (matched.length > 0) reason += `Request contains disallowed terms: ${matched.join(', ')}. `;

return [{
  json: {
    ...cfg,
    blocked,
    block_reason: reason.trim()
  }
}];

const cfg = $input.first().json;
const date = new Date().toISOString().slice(0, 10);
const finalMarkdown = `# Request Blocked by Guardrail

*Generated: ${date} · Requested by: ${cfg.requester}*

---

**Reason:** ${cfg.block_reason}

This workflow only produces defensive security research and reporting — CVE lookups, hardening checklists, threat-intel briefings, incident-report drafting, and advisory summaries — for systems you explicitly confirm you own or are authorized to assess. It never generates exploit code, malware, or intrusion instructions, and it never performs live scanning of any target.

If this was blocked in error, rephrase the request without the flagged terms and confirm authorization.
`;
return [{ json: { blocked: true, final_markdown: finalMarkdown } }];

